{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf9f6;--card:#fff;--accent:#6aa84f;--muted:#6b6b6b;--glass:rgba(255,255,255,0.6);--shadow:0 6px 18px rgba(27,31,35,0.08)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#222;background:var(--bg);}
    .page{min-height:100%;display:flex;flex-direction:column}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter:blur(6px)}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:46px;height:46px;border-radius:10px;display:grid;place-items:center;background:linear-gradient(135deg,var(--accent),#8fbf69);color:#fff;font-weight:700}
    nav a{margin-left:16px;color:#333;text-decoration:none;font-weight:600}
    main{flex:1;padding:36px 28px;max-width:1100px;margin:0 auto;}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:28px;align-items:start}
    .hero .lead{background:var(--card);padding:22px;border-radius:14px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px;font-size:22px}
    p.lead-desc{margin:0;color:var(--muted)}
    .aside{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--glass));padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    .tiers{display:flex;flex-direction:column;gap:16px;margin-top:18px}
    .tier{display:flex;justify-content:space-between;align-items:center;padding:16px;border-radius:12px;background:var(--card);box-shadow:var(--shadow)}
    .tier .meta{max-width:62%}
    .price{font-weight:800;color:var(--accent);font-size:20px}
    .badge-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}
    .cred{display:inline-flex;align-items:center;gap:8px;background:#fff;padding:8px 10px;border-radius:999px;border:1px solid rgba(0,0,0,0.04);cursor:default}
    .cred svg{width:18px;height:18px}
    .gallery{margin-top:28px;background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    .test-panel{display:flex;align-items:center;gap:12px}
    .quote{font-style:italic;color:#333}
    footer{padding:20px 28px;text-align:center;color:var(--muted);font-size:14px}
    /* rotating testimonials */
    .testimonial-rotator{position:relative}
    .test-item{display:none}
    .test-item.active{display:block}
    .controls{display:flex;gap:8px;margin-top:12px}
    .btn{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;border:none;cursor:pointer;font-weight:700}
    .secondary{background:#fff;color:var(--accent);border:1px solid rgba(0,0,0,0.06)}
    /* small tooltip */
    .tooltip{position:relative}
    .tooltip[data-tip]:hover::after{content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);white-space:nowrap;background:#222;color:#fff;padding:6px 8px;border-radius:6px;font-size:12px}
    @media(max-width:880px){.hero{grid-template-columns:1fr;}.brand .logo{width:40px;height:40px}}
  </style>
</head>
<body>
  <div class="page">
    <header>
      <div class="brand">
        <div class="logo">W</div>
        <div>
          <div style="font-weight:800">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">Story</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Paths</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Proof</a>
        <a href="book.html">Begin</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section class="hero">
        <div class="lead">
          <h1>Flexible pathways priced to meet your stage</h1>
          <p class="lead-desc">Choose how much structure you want and how much support fits your life. Each pathway centers on repeated, measurable micro-choices — habits that compound into steadier weeks.</p>

          <div class="tiers">
            <div class="tier">
              <div class="meta">
                <div style="font-weight:700">Starter Path</div>
                <div style="font-size:13px;color:var(--muted)">4 weeks of guided habit building, weekly check-ins and a simple daily rhythm.</div>
              </div>
              <div style="text-align:right">
                <div class="price">$249</div>
                <div style="font-size:12px;color:var(--muted)">One-time</div>
              </div>
            </div>

            <div class="tier">
              <div class="meta">
                <div style="font-weight:700">Momentum Plan</div>
                <div style="font-size:13px;color:var(--muted)">8 weeks with bespoke habit cycles, mid-week check-ins and habit lab experiments.</div>
              </div>
              <div style="text-align:right">
                <div class="price">$480</div>
                <div style="font-size:12px;color:var(--muted)">Billed once</div>
              </div>
            </div>

            <div class="tier">
              <div class="meta">
                <div style="font-weight:700">Keeper Membership</div>
                <div style="font-size:13px;color:var(--muted)">Ongoing support, access to micro-systems, monthly review and flexible check-ins.</div>
              </div>
              <div style="text-align:right">
                <div class="price">$65/mo</div>
                <div style="font-size:12px;color:var(--muted)">Recurring</div>
              </div>
            </div>
          </div>

          <div style="margin-top:18px;display:flex;gap:10px">
            <button class="btn" onclick="location.href='book.html'">Reserve a Starter Session</button>
            <button class="secondary" onclick="location.href='contact.html'">Ask a Question</button>
          </div>
        </div>

        <aside class="aside">
          <div style="font-weight:800">Proof Gallery</div>
          <div class="gallery">
            <div class="testimonial-rotator">
              <div class="test-item active" data-id="0">
                <div class="test-panel">
                  <div style="flex:1">
                    <div style="font-weight:700">"I finally keep morning habits that last beyond a week."</div>
                    <div class="quote" style="margin-top:6px;color:var(--muted)">— L.M., designer</div>
                  </div>
                  <div style="width:90px;text-align:right">
                    <div style="font-weight:800;color:var(--accent)">+3 habits</div>
                    <div style="font-size:12px;color:var(--muted)">sustained in 6 weeks</div>
                  </div>
                </div>
              </div>

              <div class="test-item" data-id="1">
                <div class="test-panel">
                  <div style="flex:1">
                    <div style="font-weight:700">"Small practices that feel doable and actually move the needle."</div>
                    <div class="quote" style="margin-top:6px;color:var(--muted)">— R.S., educator</div>
                  </div>
                  <div style="width:90px;text-align:right">
                    <div style="font-weight:800;color:var(--accent)">+12 sessions</div>
                    <div style="font-size:12px;color:var(--muted)">over 3 months</div>
                  </div>
                </div>
              </div>

              <div class="controls">
                <button class="secondary" id="prev">Prev</button>
                <button class="secondary" id="next">Next</button>
              </div>

              <div class="badge-row" style="margin-top:12px">
                <div class="cred tooltip" data-tip="Featured in a wellness newsletter"> 
                  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="9" stroke="#c0e0a8" stroke-width="2" fill="#eef8e9"/></svg>
                  Press
                </div>
                <div class="cred tooltip" data-tip="350+ hours of coaching logged"> 
                  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="3" width="18" height="18" rx="4" stroke="#8fc080" stroke-width="2" fill="#f3fbf2"/></svg>
                  Hours
                </div>
                <div class="cred tooltip" data-tip="Client-rated: 4.9 / 5"> 
                  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 3l2.6 5.3L20 9l-4 3.6L17 20l-5-2.6L7 20l1-7.4L4 9l5.4-.7L12 3z" stroke="#6aa84f" stroke-width="1" fill="#f7fff6"/></svg>
                  Rating
                </div>
              </div>

            </div>
          </div>
        </aside>
      </section>

      <section style="margin-top:26px">
        <div style="display:flex;gap:18px;align-items:center;justify-content:space-between;background:transparent">
          <div>
            <div style="font-weight:800">Want a tailored estimate?</div>
            <div style="color:var(--muted);font-size:13px">Tell me where you are and what you need, and I'll propose a plan that fits.</div>
          </div>
          <div>
            <a class="btn" href="book.html">Claim a Personalized Quote</a>
          </div>
        </div>
      </section>

    </main>

    <footer>
      <div>{{BUSINESS_NAME}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    </footer>
  </div>

  <script>
    (function(){
      // Rotator logic
      const items = Array.from(document.querySelectorAll('.test-item'));
      let idx = 0;
      const show = i =>{
        items.forEach(it=>it.classList.remove('active'));
        items[i].classList.add('active');
      };
      document.getElementById('next').addEventListener('click',()=>{idx=(idx+1)%items.length;show(idx)});
      document.getElementById('prev').addEventListener('click',()=>{idx=(idx-1+items.length)%items.length;show(idx)});
      let auto = setInterval(()=>{idx=(idx+1)%items.length;show(idx)},5000);
      ['next','prev'].forEach(id=>document.getElementById(id).addEventListener('mouseover',()=>clearInterval(auto)));
    })();
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Proof — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--accent:#5aa55a;--muted:#6c6c6c}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#fbfbfb, #fff);color:#222}
    .wrap{max-width:980px;margin:36px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:12px;color:#333;text-decoration:none;font-weight:600}
    .intro{background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(20,20,20,0.04);margin-top:18px}
    .rotor{display:flex;gap:16px;margin-top:18px}
    .carousel{flex:2;background:#fff;padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(20,20,20,0.04)}
    .aside{flex:1}
    .testimonial{display:none}
    .testimonial.active{display:block}
    .author{color:var(--muted);font-weight:700;margin-top:8px}
    .badges{display:flex;gap:8px;flex-wrap:wrap}
    .badge{background:#fff;padding:10px;border-radius:10px;border:1px solid rgba(0,0,0,0.04);display:flex;gap:8px;align-items:center}
    .badge svg{width:18px;height:18px}
    .controls{display:flex;gap:8px;margin-top:12px}
    .pill{background:var(--accent);color:#fff;padding:8px 12px;border-radius:999px;border:none;cursor:pointer}
    .small{background:#fff;color:var(--accent);border:1px solid rgba(0,0,0,0.06)}
    .tooltip{position:relative}
    .tooltip[data-tip]:hover::after{content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#222;color:#fff;padding:6px 8px;border-radius:6px;font-size:12px}
    /* credibility strip */
    .strip{display:flex;gap:10px;overflow:auto;margin-top:14px;padding-bottom:10px}
    .credit-card{min-width:170px;background:#fff;padding:12px;border-radius:12px;border:1px solid rgba(0,0,0,0.03);display:flex;flex-direction:column}

  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#74b36b,#9ad08b);display:grid;place-items:center;color:#fff;font-weight:800">W</div>
        <div>
          <div style="font-weight:800">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">Story</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Paths</a>
        <a href="pricing.html">Investment</a>
        <a href="book.html">Begin</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <section class="intro">
      <h2 style="margin:0 0 8px">What people notice first</h2>
      <div style="color:var(--muted)">Clients report changes in clarity, small daily wins, and routines that stick. Below are direct voices and a set of credibility indicators so you can see the work behind the words.</div>
    </section>

    <section class="rotor">
      <div class="carousel">
        <div class="testimonial active" data-index="0">
          <div style="font-weight:800">"A practical rhythm that fits real life - not just ideal days."</div>
          <div class="author">— Priya, product manager</div>
        </div>

        <div class="testimonial" data-index="1">
          <div style="font-weight:800">"Habits with context: I learned when to push and when to rest. That changed everything."</div>
          <div class="author">— Marco, teacher</div>
        </div>

        <div class="testimonial" data-index="2">
          <div style="font-weight:800">"The weekly check-ins kept me accountable without feeling pressured."</div>
          <div class="author">— Amina, nurse</div>
        </div>

        <div class="controls">
          <button class="pill" id="rot-prev">Prev</button>
          <button class="small" id="rot-next">Next</button>
          <button class="small" id="rot-play">Pause</button>
          <div style="margin-left:auto"><a class="pill" href="book.html">See Your 30-Day Map</a></div>
        </div>
      </div>

      <aside class="aside">
        <div style="font-weight:800;margin-bottom:8px">Credibility</div>
        <div class="badges">
          <div class="badge tooltip" data-tip="350+ coaching hours logged">
            <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="9" stroke="#c6e6c6" stroke-width="2" fill="#f6fff6"/></svg>Hours
          </div>
          <div class="badge tooltip" data-tip="Featured in wellness rounds">
            <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="4" y="4" width="16" height="16" rx="3" stroke="#a8dba8" stroke-width="2" fill="#f7fff7"/></svg>Press
          </div>
          <div class="badge tooltip" data-tip="Community-run workshops taught monthly">
            <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2l3 7h7l-5.6 4.2L20 22l-8-5-8 5 2.6-8.8L1 9h7z" stroke="#88c47f" stroke-width="1" fill="#f8fff9"/></svg>Workshops
          </div>
        </div>

        <div style="margin-top:16px">
          <div style="font-weight:700">Quick stats</div>
          <div class="strip">
            <div class="credit-card">Average habit retention: <strong>78%</strong><div style="font-size:12px;color:var(--muted)">after 6 weeks</div></div>
            <div class="credit-card">Client NPS: <strong>4.7</strong><div style="font-size:12px;color:var(--muted)">out of 5</div></div>
            <div class="credit-card">Repeat clients: <strong>42%</strong><div style="font-size:12px;color:var(--muted)">return within 6 months</div></div>
          </div>
        </div>
      </aside>
    </section>

  </div>

  <script>
    (function(){
      const items = Array.from(document.querySelectorAll('.testimonial'));
      let i = 0; let playing = true; let interval = null;
      const show = idx=>{items.forEach(it=>it.classList.remove('active')); items[idx].classList.add('active');}
      const start = ()=>{interval = setInterval(()=>{i=(i+1)%items.length;show(i)},4000)}
      start();
      document.getElementById('rot-next').addEventListener('click',()=>{i=(i+1)%items.length;show(i)});
      document.getElementById('rot-prev').addEventListener('click',()=>{i=(i-1+items.length)%items.length;show(i)});
      document.getElementById('rot-play').addEventListener('click',function(){if(playing){clearInterval(interval);this.textContent='Play';playing=false}else{start();this.textContent='Pause';playing=true}});
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fcfdf9;--accent:#5eac59;--muted:#666}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:#222}
    .container{max-width:1000px;margin:28px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:12px;color:#333;text-decoration:none;font-weight:600}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:18px;margin-top:18px}
    .card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(20,20,20,0.04)}
    h1{margin:0 0 6px}
    .choices{display:flex;flex-direction:column;gap:10px;margin-top:12px}
    .goal{display:flex;align-items:center;gap:10px}
    input[type=checkbox]{width:18px;height:18px}
    .meter{margin-top:12px}
    .path-map{display:flex;gap:6px;flex-wrap:nowrap;overflow:auto;padding:8px 0}
    .day{width:38px;height:38px;border-radius:8px;background:linear-gradient(180deg,#fff,#f6f6f6);display:grid;place-items:center;font-size:12px;border:1px solid rgba(0,0,0,0.04)}
    .legend{display:flex;gap:8px;align-items:center;margin-top:10px}
    .dot{width:12px;height:12px;border-radius:3px}
    .cta{margin-top:14px}
    .btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:none;cursor:pointer;font-weight:700}
    form label{display:block;margin-top:12px}
    input[type=text],input[type=email],input[type=tel],select{width:100%;padding:10px;border-radius:8px;border:1px solid #e7e7e7}
    .preview{font-size:13px;color:var(--muted);margin-top:8px}
    @media(max-width:920px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#6fb46f,#9bd98b);display:grid;place-items:center;color:#fff;font-weight:800">W</div>
        <div>
          <div style="font-weight:800">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">Story</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Paths</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Proof</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <div class="grid">
      <section class="card">
        <h1>Reserve your starter session</h1>
        <div class="preview">Pick the outcomes that matter most and see a tailored 30-day map. This helps us begin with a clear, practical first month.</div>

        <div class="choices" id="goals">
          <label class="goal"><input type="checkbox" value="sleep">Improve sleep regularity</label>
          <label class="goal"><input type="checkbox" value="energy">Boost steady daytime energy</label>
          <label class="goal"><input type="checkbox" value="routine">Create a morning/evening routine</label>
          <label class="goal"><input type="checkbox" value="stress">Build small stress-relief practices</label>
          <label class="goal"><input type="checkbox" value="movement">Add short movement breaks</label>
        </div>

        <div class="meter card" id="meter" style="margin-top:12px">
          <div style="font-weight:700">Your 30-day Path Map</div>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">Each day shows a micro-action. The path changes based on goals you choose.</div>
          <div class="path-map" id="map"></div>
          <div class="legend">
            <div style="display:flex;gap:6px;align-items:center"><div class="dot" style="background:#f6f6f6;border:1px solid #e4e4e4"></div><div style="font-size:13px;color:var(--muted)">Neutral</div></div>
            <div style="display:flex;gap:6px;align-items:center"><div class="dot" style="background:#ffd59a"></div><div style="font-size:13px;color:var(--muted)">Small change</div></div>
            <div style="display:flex;gap:6px;align-items:center"><div class="dot" style="background:#c9e9c9"></div><div style="font-size:13px;color:var(--muted)">Core practice</div></div>
          </div>
        </div>

        <div style="margin-top:14px">
          <form id="bookForm">
            <label>Name<input type="text" name="name" required placeholder="Your name"></label>
            <label>Email<input type="email" name="email" required placeholder="you@domain.com"></label>
            <label>Phone<input type="tel" name="phone" placeholder="Optional"></label>
            <label>Preferred Session<select name="session">
              <option>30-minute starter</option>
              <option>60-minute deep session</option>
            </select></label>
            <div class="cta"><button class="btn" type="submit">See Your 30-Day Map</button></div>
          </form>
          <div id="formMsg" style="margin-top:10px;color:var(--muted);font-size:13px"></div>
        </div>
      </section>

      <aside class="card">
        <div style="font-weight:800">What to expect in month one</div>
        <ul style="color:var(--muted);margin-top:10px">
          <li>Daily micro-actions that stack into a rhythm</li>
          <li>Two short check-ins and a weekly email note</li>
          <li>Tools you can keep using without extra time demands</li>
        </ul>

        <div style="margin-top:12px">
          <div style="font-weight:700">Quick booking</div>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">If you'd like, use this to create a tentative plan. We'll confirm details after you book.</div>
          <div style="margin-top:12px"><a class="btn" href="mailto:{{EMAIL}}?subject=Booking%20Request">Request availability</a></div>
        </div>

        <div style="margin-top:18px">
          <div style="font-weight:700">Need to know</div>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">Outcomes are framed around habits and repeatable choices — there are no medical recommendations here.</div>
        </div>
      </aside>
    </div>
  </div>

  <script>
    (function(){
      const goalMap = {
        sleep: {color:'#c9e9c9',micro:['bedtime wind-down (10m)','no screens 30m before bed','light stretch before bed']},
        energy:{color:'#ffd59a',micro:['15m brisk walk','midday 5-min breath','2 glass water on waking']},
        routine:{color:'#c9e9c9',micro:['5-min morning plan','one evening tidy','set tomorrow's top 3']},
        stress:{color:'#ffd59a',micro:['3-min breath pause','progressive muscle 5m','write one thing that went well']},
        movement:{color:'#c9e9c9',micro:['3x micro-moves 2-3m','desk stretch','short walk after lunch']}
      };

      const mapEl = document.getElementById('map');
      const goalInputs = Array.from(document.querySelectorAll('#goals input[type=checkbox]'));

      function buildMap(){
        const active = goalInputs.filter(i=>i.checked).map(i=>i.value);
        mapEl.innerHTML = '';
        const days = 30;
        // for each day, pick 1-2 micro-actions from active goals in a rotating manner
        for(let d=1;d<=days;d++){
          const box = document.createElement('div');
          box.className='day';
          let color = '#fff';
          let label = d;
          if(active.length===0){box.style.opacity='0.6';box.title='No goals selected';}
          else{
            // pick goal by rotating index
            const pick = active[(d-1)%active.length];
            const microList = goalMap[pick].micro;
            const micro = microList[(d-1)%microList.length];
            color = goalMap[pick].color;
            box.style.background = color;
            box.title = micro + ' ('+pick+')';
          }
          box.textContent = d;
          mapEl.appendChild(box);
        }
      }

      goalInputs.forEach(i=>i.addEventListener('change',buildMap));
      buildMap();

      // Form submit shows a tailored text and prevents navigation
      document.getElementById('bookForm').addEventListener('submit',function(e){
        e.preventDefault();
        const data = new FormData(this);
        const name = data.get('name')||'there';
        const selected = goalInputs.filter(i=>i.checked).map(i=>i.value);
        const msg = selected.length?('Thanks, '+name+'. Based on your selection I prepared a 30-day micro-plan. We will email next steps to '+data.get('email')+'.'):
                  ('Thanks, '+name+'. We will follow up to clarify outcomes and build your 30-day map.');
        document.getElementById('formMsg').textContent = msg;

        // show a lightweight on-page preview of day 1-6 micro-actions
        const preview = document.createElement('div');
        preview.style.marginTop='12px';
        preview.style.padding='12px';
        preview.style.background='#fbfff9';
        preview.style.borderRadius='8px';
        preview.style.border='1px solid rgba(0,0,0,0.03)';
        let html = '<strong>Preview — first week</strong>\n<ul style="margin:8px 0 0 14px">';
        if(selected.length===0){html += '<li>We will begin by clarifying your top priority in our call.</li>';}
        else{
          for(let d=1;d<=7;d++){
            const pick = selected[(d-1)%selected.length];
            const micro = goalMap[pick].micro[(d-1)%goalMap[pick].micro.length];
            html += '<li>Day '+d+': '+micro+' ('+pick+')</li>';
          }
        }
        html += '</ul>';
        preview.innerHTML = html;
        const existing = document.querySelector('.card .preview-week');
        if(existing) existing.remove();
        preview.className = 'preview-week';
        document.querySelector('.card').appendChild(preview);

        // Optionally, could redirect to an external booking link: location.href='{{PRIMARY_CTA_URL}}'
      });
    })();
  </script>
</body>
</html>"} 
